func HasChildrenWith(preds ...predicate.ContentNode) predicate.ContentNode {
	return predicate.ContentNode(func(s *sql.Selector) {
		step := newChildrenStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasPlacements applies the HasEdge predicate on the "placements" edge.
func HasPlacements() predicate.ContentNode {
	return predicate.ContentNode(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, PlacementsTable, PlacementsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPlacementsWith applies the HasEdge predicate on the "placements" edge with a given conditions (other predicates).
func HasPlacementsWith(preds ...predicate.ContentPlacement) predicate.ContentNode {
	return predicate.ContentNode(func(s *sql.Selector) {
		step := newPlacementsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ContentNode) predicate.ContentNode {
	return predicate.ContentNode(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ContentNode) predicate.ContentNode {
	return predicate.ContentNode(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ContentNode) predicate.ContentNode {
	return predicate.ContentNode(sql.NotPredicates(p))
}
